import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Installation","description":"Install S3 Database Storage for VPS, run the setup wizard, verify the schedule, and uninstall.","frontmatter":{"title":"Installation","description":"Install S3 Database Storage for VPS, run the setup wizard, verify the schedule, and uninstall."},"headers":[],"relativePath":"s3-database-storage-for-vps/getting-started/installation.md","filePath":"s3-database-storage-for-vps/getting-started/installation.md","lastUpdated":1782847089000}'),n={name:"s3-database-storage-for-vps/getting-started/installation.md"};function l(o,s,p,r,h,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Linux VPS (Debian/Ubuntu, RHEL/Fedora, etc.) with <strong>root/sudo</strong>.</li><li><strong>Python 3.8+</strong>.</li><li>Client tools for whatever you back up (the installer tries to install these for you): <ul><li>PostgreSQL: <code>pg_dump</code> / <code>psql</code> — package <code>postgresql-client</code></li><li>MySQL/MariaDB: <code>mysqldump</code> / <code>mysql</code> — package <code>default-mysql-client</code> or <code>mariadb-client</code></li></ul></li><li>An <strong>S3-compatible bucket</strong> and an access key / secret key.</li></ul><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AnAverageBeing/s3-database-storage-for-vps.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3-database-storage-for-vps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>The installer:</p><ol><li>Installs system dependencies (<code>python3</code>, <code>pip</code>, <code>gzip</code>, database client tools).</li><li>Copies the program to <code>/opt/s3dbbackup</code> and creates an isolated Python virtualenv there.</li><li>Creates the <code>s3dbbackup</code> command at <code>/usr/local/bin/s3dbbackup</code>.</li></ol><h2 id="_2-run-the-setup-wizard" tabindex="-1">2. Run the setup wizard <a class="header-anchor" href="#_2-run-the-setup-wizard" aria-label="Permalink to &quot;2. Run the setup wizard&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>The wizard walks you through nine short steps:</p><ol><li><strong>S3 storage</strong> — endpoint, region, access key, secret key, bucket, path-style toggle.</li><li><strong>Folder</strong> — a prefix everything is stored under.</li><li><strong>Connection test</strong> — it won&#39;t continue until S3 responds.</li><li><strong>Pick databases</strong> — choose from an auto-detected, numbered list (<code>1,3,4</code> or <code>all</code>).</li><li><strong>Local copy</strong> — optionally keep a copy on the node.</li><li><strong>Frequency</strong> — hourly / 6h / 12h / daily / weekly / custom.</li><li><strong>Retention</strong> — how many copies to keep per database.</li><li><strong>Discord alerts</strong> — optional webhook + event selection.</li><li><strong>Schedule</strong> — it writes and enables the systemd timer, then offers to run a backup now.</li></ol><div class="tip custom-block"><p class="custom-block-title">Recommended values</p><ul><li><strong>Cloudflare R2</strong>: Region <code>auto</code>, path-style <strong>on</strong>.</li><li><strong>DigitalOcean Spaces</strong>: Region = datacenter (e.g. <code>sgp1</code>), path-style <strong>on</strong>.</li><li><strong>AWS S3</strong>: leave Endpoint blank, set the region, path-style <strong>off</strong>.</li><li><strong>Frequency</strong>: <code>daily</code> for most servers; <code>every 6 hours</code> for busy databases.</li><li><strong>Max copies</strong>: <code>7</code> (a week of dailies).</li></ul></div><h2 id="_3-verify" tabindex="-1">3. Verify <a class="header-anchor" href="#_3-verify" aria-label="Permalink to &quot;3. Verify&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Show config, last run, and next scheduled run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Confirm the timer is active and see the next trigger time</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-timers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup.timer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run a backup on demand</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span></code></pre></div><p>After a run, check your bucket — objects appear under:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;bucket&gt;/&lt;folder&gt;/&lt;db-type&gt;/&lt;db-name&gt;/&lt;timestamp&gt;.sql.gz</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><details class="details custom-block"><summary>No databases were detected</summary><p>The wizard scans using local/peer authentication. If your databases require a password, choose <strong>Add databases manually</strong> (or answer &quot;yes&quot; when asked whether the dumps need explicit credentials) and provide host/port/user/password.</p></details><details class="details custom-block"><summary><code>pg_dump</code>/<code>mysqldump</code> not found</summary><p>Install the client tools:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Debian/Ubuntu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql-client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default-mysql-client</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># RHEL/Fedora</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span></span></code></pre></div></details><details class="details custom-block"><summary>S3 connection fails</summary><p>Double-check the <strong>endpoint</strong>, <strong>region</strong>, and <strong>path-style</strong> setting for your provider. Most non-AWS providers (R2, MinIO, Spaces, B2) require path-style <strong>on</strong>. The wizard lets you edit and retry without restarting.</p></details><details class="details custom-block"><summary>The timer isn&#39;t running</summary><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup.timer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup.timer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # see backup run logs</span></span></code></pre></div></details><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Removes the timer, command, and /opt/s3dbbackup — keeps your config</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Also remove /etc/s3dbbackup (config)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --purge</span></span></code></pre></div><p>Local backup files under <code>/var/backups/s3dbbackup</code> (or your chosen path) and any objects already in S3 are left untouched.</p>`,24)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
